function pour(cups) {
  console.log("pour");

  if (cups > 2) {
    throw new Error("pot is empty");
  }

  console.log("poured");
}

function serve(cups) {
  pour(cups);
  console.log("served");
}

try {
  serve(1);
  serve(3);
  serve(1);
} catch (error) {
  console.log(error.message);
}

console.log("done");
